document.addEventListener('change',e=>{const el=e.target,a=el.dataset.change,id=el.dataset.id;switch(a){case'dish-size':{const m=currentWeek().days[editingDate][editingType];if(m.cooked)return;const r=m.recipes[+el.dataset.index];if(el.value==='auto')delete r.portionFactor;else r.portionFactor=+el.value;save('Đã tính lại lượng nấu từng món.');render();editMeal(editingDate,editingType);break}case'meal-staple':{const m=currentWeek().days[editingDate][editingType];if(m.cooked)return;m.staple=el.value;save('Đã cập nhật món cơm ăn kèm.');render();break}case'attendance':{const m=currentMeal();if(m.cooked)return;m.attendance[id]=el.value;m.tasks={};log(`${state.members.find(m=>m.id===id)?.name} cập nhật báo cơm ${dateLabel(selectedDate)}`);save('Đã tính lại khẩu phần và danh sách mua.');render();break}case'meal-note':currentMeal().note=el.value.slice(0,1000);save('Đã lưu ghi chú.');break;case'task':currentMeal().tasks[id]=el.checked;save();render();break;case'lunch-toggle':state.preferences.lunch=el.checked;if(!el.checked)attendanceType='dinner';save();render();break;case'shop-range':shopRange=el.value;render();break;case'pack-toggle':state.preferences.packed=el.checked;save();render();break;case'bought':{const[start,end]=shopDates(),row=shopping(state,currentWeek(),start,end).find(r=>r.id===id);if(row)setShoppingBought(currentWeek(),start,end,row,el.checked);save();render();break}case'extra-done':{const item=currentWeek().extras.find(x=>x.id===id);if(item){item.done=el.checked;if(item.done)item.boughtAt=new Date().toISOString();else delete item.boughtAt;save();render()}break;}case'skip-stock':currentWeek().skip[id]=el.checked;save();render();break;case'recipe-time':recipeTime=+el.value;recipePage=0;render();break}if(el.id==='stock-ing')$('#stock-unit').textContent=INGREDIENTS[el.value][1]});
